// Via backend proxy API
const response = await fetch('/api/v1/breakout-candidates');
const { data, metadata } = await response.json();

// Sort by opportunity score (highest first)
const sorted = data.sort((a, b) => b.opportunity_score - a.opportunity_score);

// Display
sorted.forEach(candidate => {
  console.log(`${candidate.player_name}: ${candidate.opportunity_score.toFixed(2)} score`);
});
